/**
 * Health A–Z (/health, /it/health, /de/health): a lexicon of the symptoms and conditions our own articles cover.
 *
 * CONTENT RULES (checked by `node scripts/check-health-terms.mjs`, part of `npm run build`):
 *  - Every term exists only because at least one of our articles covers it; `slugs` are those articles, in the
 *    same language, most relevant first.
 *  - `text` is one or two plain sentences that paraphrase (or quote) the opening, description or a heading answer
 *    of the linked articles and adds nothing. No doses, no product advice, no banned sources (scripts/check-sources.mjs).
 *  - `synonyms` are words owners type ("throwing up", "Kotzen"); the page searches names and synonyms of all
 *    three languages, so a German word on the English page still finds the English entry.
 *  - Animals and urgency pills are not written here: they come from the linked articles' frontmatter
 *    (species, animals, urgency). `species` adds animals only for terms whose articles are filed as "general".
 *
 * Anchors: English uses `key` (#vomiting); Italian and German use the slugified name (#vomito, #erbrechen)
 * unless `anchor` pins one. Pin an anchor before renaming an entry so existing links keep working.
 */
export const LANGS = ['en', 'it', 'de'] as const;
export type Lang = (typeof LANGS)[number];
export const ANIMALS = ['dog', 'cat', 'rabbit', 'guinea-pig', 'ferret', 'horse', 'bird', 'reptile'] as const;
export type Animal = (typeof ANIMALS)[number];
export const URGENCIES = ['emergency', 'today', 'this-week', 'routine'] as const;
export type Urgency = (typeof URGENCIES)[number];

export interface TermText { name: string; synonyms: string[]; text: string; slugs: string[]; anchor?: string }
export interface Term {
  key: string;
  kind: 'symptom' | 'condition';
  /** Animals for terms whose articles are all filed under "general" (dogs and cats, etc.). */
  species?: Animal[];
  en?: TermText; it?: TermText; de?: TermText;
}

const t = (name: string, synonyms: string[], text: string, slugs: string[]): TermText => ({ name, synonyms, text, slugs });

