export const fold = (s: string) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/ß/g, 'ss').replace(/[’`]/g, "'").replace(/\s+/g, ' ').trim();
const slug = (s: string) => fold(s).replace(/\([^)]*\)/g, ' ').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
/** The entry's anchor on its language's page: #vomiting, #vomito, #erbrechen. */
export const anchorOf = (term: Term, lang: Lang) => term[lang]!.anchor ?? (lang === 'en' ? term.key : slug(term[lang]!.name));
/** Terms that exist in a language. */
export const termsIn = (lang: Lang) => TERMS.filter((x) => x[lang]);
/** Every search word of a term in all three languages (the page matches any of them). */
export const searchWords = (term: Term) => LANGS.flatMap((l) => (term[l] ? [term[l]!.name, ...term[l]!.synonyms] : []));
export const healthPath = (lang: Lang) => (lang === 'en' ? '/health' : `/${lang}/health`);

